    # status[n] will be True if n is an N-position (Next player winning, W), False if P-position (Previous player winning, L)
    # We analyze positions from N-1 down to 1.
    status = {}

    # Iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):

        # Potential moves from n: n+1 and 2n
        moves = []
        if n + 1 <= N:
            moves.append(n + 1)
        if 2 * n <= N:
            moves.append(2 * n)

        if not moves:
            # This should only happen if n=N, but we stop at N-1. 
            # If N is very small (e.g., N=1, loop doesn't run), but we handle N >= 2 here.
            # For n < N, there must be a move unless N=1 (handled outside).
            continue 

        # n is an N-position (W) if there is at least one move to an L-position (P)
        is_winning = False
        for m in moves:
            if m == N:
                # Moving directly to N is a winning move for the current player
                is_winning = True
                break
            elif m < N:
