def solve_game(N):
    """
    Determines if the starting position 1 is a Winning (True) or Losing (False)
    position for Player A, given the maximum limit N.
    Returns True if A wins (Type A), False if B wins (Type B).
    """
    if N == 1:
        return True

    # Win[n] stores the result for position n.
    Win = {}

    # Iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):
        moves = []

        # Check move n+1
        if n + 1 <= N:
            moves.append(n + 1)

        # Check move 2n
        if 2 * n <= N:
            moves.append(2 * n)

        is_winning = False
        for next_n in moves:
            if next_n == N:
                is_winning = True
                break

            # Check if the opponent loses from next_n
            if not Win[next_n]:
                is_winning = True
                break

        Win[n] = is_winning

    # We start at n=1.
    return Win.get(1, False)

