def solve_game(N):
    """
    Determines if the starting position (n=1) is a Winning (Type A) or Losing (Type B) position 
    for the first player, given the game ends at N.
    """
    if N == 1:
        # Player A writes 1, reaching N=1 and winning immediately.
        return False # Type A (not Type B)

    # status[n] is True if the current player starting at n wins (N-position), 
    # False if the current player starting at n loses (P-position).
    status = {} 

    # Iterate backward from N-1 down to 1
    for n in range(N - 1, 0, -1):
        can_win = False

        # Possible next moves are n+1 and 2n, provided they do not exceed N
        moves = []
        if n + 1 <= N:
            moves.append(n + 1)
        if 2 * n <= N:
            moves.append(2 * n)

        # Check for immediate win (moving to N)
        if N in moves:
            can_win = True
        else:
            # Check if any move leads to a losing position (P-position) for the opponent.
            for m in moves:
                # We know m < N here since N is handled above
                if not status[m]:
                    can_win = True
                    break

        status[n] = can_win

    # N is Type B if the starting position (n=1) is a losing position (False).
    return not status[1]

