def is_type_A(N):
    """
    Determines if N is Type A (Player A wins) or Type B (Player B wins).
    N is Type A if n=1 is a winning position (N-position).
    N is Type B if n=1 is a losing position (P-position).
    """
    if N <= 1:
        return False # Trivial case, though problem requires N > 400

    # S[n] = True means Winning (N-position), False means Losing (P-position)
    S = [False] * (N + 1) 

    # We compute S[n] iteratively from N-1 down to 1
    for n in range(N - 1, 0, -1):
        can_win = False

        # Check move n + 1
        n_plus_1 = n + 1
        if n_plus_1 == N:
            can_win = True
        elif n_plus_1 < N:
            # If moving to n+1 leads to a losing state (P-position) for the opponent
            if not S[n_plus_1]:
                can_win = True

        # Check move 2 * n
        n_times_2 = 2 * n
        if not can_win: # Optimization: only check 2n if we haven't found a winning move yet
            if n_times_2 == N:
                can_win = True
            elif n_times_2 < N:
                # If moving to 2n leads to a losing state (P-position) for the opponent
                if not S[n_times_2]:
                    can_win = True

        S[n] = can_win

    # If S[1] is True, Player A wins (Type A). If False, Player B wins (Type B).
    return S[1]

